import {esc} from './customer-shared.mjs';
export function briefMarkup(b){return `<p class="story-label">${esc(b.method)} · evidence-linked explanation</p><div class="story-brief">${[['What we found',b.found],['What we recommend',b.recommendation],['What keeps the change controlled',b.guardrail],['What remains uncertain',b.unknown]].map(([t,p])=>`<div><strong>${t}</strong><p>${esc(p)}</p></div>`).join('')}</div>`;}
export function factsMarkup(f){const duration=f.durationSeconds===null?'Not recorded':f.durationSeconds<60?f.durationSeconds+'s':Math.floor(f.durationSeconds/60)+'m '+f.durationSeconds%60+'s';return `<p class="story-label">${esc(f.recordType)} · measured from this case’s recorded events</p><div class="story-metrics">${[[duration,f.durationLabel],[f.messages??'Unavailable','Customer / merchant messages'],[f.accessGrants,'Access grants applied'],[f.verificationAttempts,'Verification attempts']].map(([n,t])=>`<div><strong>${esc(n)}</strong><span>${esc(t)}</span></div>`).join('')}</div><p><strong>System verified access:</strong> ${f.systemVerified?'Yes':'Not confirmed'}<br><strong>Customer confirmed success:</strong> ${f.customerConfirmed?'Yes':f.customerNeedsHelp?'Still needs help':'Not yet'}</p><p class="story-label">${f.approvedAt?'Approval recorded '+esc(new Date(f.approvedAt).toLocaleString()):'No approval recorded'}. These figures do not establish saved revenue or prevented disputes.</p>`;}
export function downloadFacts(f){const url=URL.createObjectURL(new Blob([JSON.stringify(f,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=f.caseId+'-outcome-facts.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
